const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

// Helper function to calculate NDVI for Landsat 4/5/7
function addNDVI(image) {
  const ndvi = image.normalizedDifference(['SR_B4', 'SR_B3']).rename('NDVI');
  return image.addBands(ndvi);
}

// Helper function to mask clouds in Landsat 4/5/7 based on QA_PIXEL
function maskL457(image) {
  const qa = image.select('QA_PIXEL');
  // Bits 3 and 5 are cloud shadow and cloud, respectively.
  const cloudShadowBitMask = (1 << 3);
  const cloudsBitMask = (1 << 5);
  // Both flags should be 0, indicating clear conditions.
  const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                 .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
  return image.updateMask(mask);
}

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const roi = ee.Geometry.Point([22.0, -23.0]).buffer(5000); // Central Kalahari Desert
  const date2009 = ee.Date('2009-04-19');
  const date2008 = ee.Date('2008-08-06');
  const scale = 1000; // Use a coarse scale for regional analysis to avoid timeouts

  // 2. Data Acquisition
  const collection = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2');

  const col2009 = collection
    .filterBounds(roi)
    .filterDate(date2009, date2009.advance(1, 'day'));

  const col2008 = collection
    .filterBounds(roi)
    .filterDate(date2008, date2008.advance(1, 'day'));

  // 3. Data Availability Check
  const size2009 = col2009.size().getInfo();
  const size2008 = col2008.size().getInfo();

  console.log(`Images found for 2009-04-19: ${size2009}`);
  console.log(`Images found for 2008-08-06: ${size2008}`);

  if (size2009 === 0 || size2008 === 0) {
    console.log("No images found for one or both dates.");
    console.log("A: No");
    return;
  }

  // 4. Processing and Calculation
  const image2009 = col2009.map(maskL457).map(addNDVI).median();
  const image2008 = col2008.map(maskL457).map(addNDVI).median();

  const ndviReducer = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const stats2009 = image2009.reduceRegion({
    reducer: ndviReducer,
    geometry: roi,
    scale: scale,
    maxPixels: 1e9
  });

  const stats2008 = image2008.reduceRegion({
    reducer: ndviReducer,
    geometry: roi,
    scale: scale,
    maxPixels: 1e9
  });

  // Execute the computations
  const results = ee.Dictionary({
      'stats2009': stats2009,
      'stats2008': stats2008
  }).getInfo();

  const ndvi2009 = results.stats2009.NDVI_mean;
  const pixels2009 = results.stats2009.NDVI_count;
  const ndvi2008 = results.stats2008.NDVI_mean;
  const pixels2008 = results.stats2008.NDVI_count;

  // 5. Validation and Final Answer
  if (pixels2009 === 0 || pixels2008 === 0) {
    console.log(`Valid pixels 2009: ${pixels2009}`);
    console.log(`Valid pixels 2008: ${pixels2008}`);
    console.log("No valid pixels after cloud masking for one or both dates.");
    console.log("C2");
    return;
  }

  if (ndvi2009 === null || ndvi2008 === null) {
      console.log(`NDVI 2009: ${ndvi2009}`);
      console.log(`NDVI 2008: ${ndvi2008}`);
      console.log("Calculation failed, result is null.");
      console.log("C3");
      return;
  }

  console.log(`2009-04-19 Mean NDVI: ${ndvi2009.toFixed(4)} (Pixels: ${pixels2009})`);
  console.log(`2008-08-06 Mean NDVI: ${ndvi2008.toFixed(4)} (Pixels: ${pixels2008})`);

  if (ndvi2009 > ndvi2008) {
    console.log("A: Yes");
  } else {
    console.log("B: No");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log("D");
});
